  var fW=findForm(ctx,'Walks & Visits'),fC=findForm(ctx,'Clients'),fP=findForm(ctx,'Pets'),fT=findForm(ctx,'Team Members'),fI=findForm(ctx,'Incidents & Care Notes');
  var r=await Promise.all([recs(fW),recs(fC),recs(fP),recs(fT),recs(fI)]);
