  book.sort(function(x,y){return x.dd-y.dd||String(x.a.time||'').localeCompare(String(y.a.time||''));});
  var openFu=0,uh30=0;
  for(var j=0;j<incidents.length;j++){var ia=incidents[j].answers||{};var idd=dayDiff(incidents[j].submittedAt);if(ia.follow_up==='yes')openFu++;if((ia.severity==='urgent'||ia.severity==='high')&&idd!=null&&idd>=-30&&idd<=0)uh30++;}
  var list=book.slice(0,8),bookMode='up';
  if(!list.length&&walks.length){bookMode='latest';var lat=walks.slice().sort(function(x,y){var xd=pd((x.answers||{}).date),yd=pd((y.answers||{}).date);return (yd?yd.getTime():0)-(xd?xd.getTime():0);});list=[];for(var k=0;k<Math.min(8,lat.length);k++){var ka=lat[k].answers||{};list.push({a:ka,dd:dayDiff(ka.date)});}}
  var nextClause='';
  if(todayN>0&&nextT)nextClause='next at <b>'+h(fmtTime(nextT))+'</b>';
  else if(bookMode==='up'&&list.length&&list[0].dd>0)nextClause='next '+h(ago(list[0].a.date));
  var html='<div class="wrap">';
  html+=headerBlock(PAW,ctx.appName||'PawRoute',brief(['<b>'+fmtInt(todayN)+'</b> walk'+(todayN===1?'':'s')+' today',nextClause,'<b>'+mnyC(revWeek)+'</b> this week',openFu>0?'<b>'+fmtInt(openFu)+'</b> open follow-up'+(openFu===1?'':'s'):'no open follow-ups']),[{nav:fW?fW.formId:'',label:'New walk',icon:I.plus},{nav:fP?fP.formId:'',label:'Add pet',icon:PAW,ghost:true}]);
  html+='<div class="kpis">'
    +(weekN===0&&upN>0?kpi('On the route',upN,'<b>'+fmtInt(weekN)+'</b> this week \u00b7 <b>'+fmtInt(todayN)+'</b> today',{hero:true,spark:spark(weekly(walks))}):kpi('This week',weekN,walks.length?'<b>'+fmtInt(todayN)+'</b> today':'No walks yet',{hero:true,spark:spark(weekly(walks))}))
    +kpi('Today',todayN,todayN>0&&nextT?'next at <b>'+h(fmtTime(nextT))+'</b>':'none on the route today')
