      var pnm=refName(pn,e.a.pet)||refName(cn,e.a.client)||'Walk';var sv=e.a.service_type?labelFor(svcMap,e.a.service_type):'Walk';var wkr=refName(tn,e.a.walker);
      tlHtml+='<div class="sch"><span class="sch-t num">'+h(fmtTime(e.a.time)||'\u2014')+'</span><div class="row-main"><div class="row-title">'+h(pnm)+'</div><div class="row-sub">'+h(sv+(wkr?' \u00b7 '+wkr:''))+'</div></div><div class="row-r">'+stPill(stMap,e.a.status)+'</div></div>';}
