  if(!ihHtml&&incidents.length){for(var q2=0;q2<Math.min(5,isort.length);q2++){var da=isort[q2].answers||{};ihHtml+=qRow(SEVC[da.severity]||'var(--fl-accent)',h(refName(pn,da.pet)||'Care note'),h((da.incident_type?labelFor(typeMap,da.incident_type):'')||da.description||'Care note'),da.severity?pill(labelFor(sevMap,da.severity),SEVP[da.severity]||'neutral'):'');}}
