  html+=sec('Crew & care')+'<div class="grid g11">'+panel('Walker workload',wlHtml,fT?'form/'+fT.formId+'/responses':'')+panel('Pets needing attention',ihHtml,fI?'form/'+fI.formId+'/responses':'')+'</div>';
